/* @lc app=leetcode id=1178 lang=kotlin */ class Solution { fun findNumOfValidWords(words: Array<String>, puzzles: Array<String>): List<Int> = words.groupingBy { w -> w.fold(0) { m, c -> m or (1 shl (c - 'a')) } }.eachCount().let { cnt -> puzzles.map { p -> (0 until 64).sumOf { s -> cnt[(1 shl (p[0] - 'a')) or (1..6).filter { s shr (it - 1) and 1 == 1 }.fold(0) { m, i -> m or (1 shl (p[i] - 'a')) }] ?: 0 } } } }